records.bodyExcerpt:
function computeScopedCoreFactsHash(StreamFinalityScope calldata scope)
        external
        view
        returns (bytes32);

function finalizeCollectionArtwork(
        uint256 collectionId,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 expectedFinalityRecordHash,
        StreamFinalityManifestRef calldata manifest
    ) external;

function verifyArtworkScopeFinality(StreamFinalityScope calldata scope)
        external
        view
        returns (bool currentRouteMatches, bytes32 finalityRecordHash, bytes32 componentsHash);

function contentRootScopeSubject(StreamFinalityScope calldata scope)
        external
        view
        returns (bytes32);

function stageFinalityManifest(bytes calldata manifestBytes)
        external
        returns (bytes32 contentHash);

function artworkScopeFinalityRecord(StreamFinalityScope calldata scope)
        external
        view
        returns (StreamScopedFinalityRecord memory);

function computeNonSanctionComponentsHash(StreamFinalityComponentExpectation[] calldata components)
        external
        pure
        returns (bytes32);

function computeSanctionSubjectHash(
        StreamFinalityScope calldata scope,
        bytes32 coreFactsHash,
        bytes32 nonSanctionComponentsHash,
        StreamFinalityManifestRef calldata manifest
    ) external view returns (bytes32);

function collectionFinalityRecord(uint256 collectionId)
        external
        view
        returns (StreamCollectionFinalityRecord memory);

function verifyFinalityRange(uint256 collectionId, uint256 start, uint256 limit)
        external
        view
        returns (
            bool rangeMatches,
            bytes32 finalityRecordHash,
            bytes32 expectedRangeHash,
            bytes32 observedRangeHash,
            uint256 nextStart
        );

function scheduleArtworkTerminalFreeze(
        StreamFinalityScope calldata scope,
        bytes32 expectedFinalityRecordHash,
        uint64 notBefore,
        uint64 expiresAfter
    ) external;

function finalizeArtworkScope(
        StreamFinalityScope calldata scope,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 expectedFinalityRecordHash,
        StreamFinalityManifestRef calldata manifest
    ) external;

function computeFinalityRecordHash(
        StreamFinalityScope calldata scope,
        bytes32 coreFactsHash,
        bytes32 componentsHash,
        StreamFinalityManifestRef calldata manifest
    ) external view returns (bytes32);

function finalityComponentsForScope(
        StreamFinalityScope calldata scope,
        uint256 start,
        uint256 limit
    ) external view returns (StreamFinalityComponentExpectation[] memory);

function verifyFinality(uint256 collectionId)
        external
        view
        returns (bool currentRouteMatches, bytes32 finalityRecordHash, bytes32 componentsHash);

function assetPolicy(address asset)
        external
        view
        returns (uint8 status, bytes32 policyHash, uint64 effectiveAt);

function registerAuction(
        bytes32 _dropId,
        uint256 _tokenid,
        uint256 _collectionId,
        address _poster,
        uint256 _reservePrice,
        uint256 _auctionEndTime
    ) external;

function collectionRecord(uint256 collectionId, bytes32 recordType)
        external
        view
        returns (CollectionMetadataRecordView memory);

function setCollectionRecordWithRevision(
        uint256 collectionId,
        CollectionMetadataRecord calldata record,
        uint64 expectedRevision
    ) external returns (bytes32 recordHash);

function deriveCollectionRecordHash(
        uint256 collectionId,
        CollectionMetadataRecord calldata record,
        uint64 revision
    ) external view returns (bytes32);

function collectionSnapshot(uint256 collectionId, bytes32 snapshotId)
        external
        view
        returns (CollectionMetadataRecordView memory);

function snapshotCoveredRecordTypesHash(uint256 collectionId, bytes32 snapshotId)
        external
        view
        returns (bytes32);

function latestCollectionRecordHash(uint256 collectionId, bytes32 recordType)
        external
        view
        returns (bytes32);

function setCollectionRecord(uint256 collectionId, CollectionMetadataRecord calldata record)
        external
        returns (bytes32 recordHash);

function collectionRecordTypeAt(uint256 collectionId, uint256 index)
        external
        view
        returns (bytes32);

function publishCollectionSnapshot(
        uint256 collectionId,
        bytes32 snapshotId,
        bytes32[] calldata coveredRecordTypes,
        CollectionMetadataRecord calldata snapshot
    ) external returns (bytes32 snapshotHash);

records.summary:
@notice Publishes an immutable SNAPSHOT-family record.
 @dev Snapshot publication is blocked by `METADATA_ALL`, `SNAPSHOTS`, or the snapshot
 record's own `recordType` lock. The caller must also hold authority for every exact
 record type in `coveredRecordTypes`.

